type Ambiente = Record<string, string | undefined>;

function carregaConfig(env: Ambiente) {
  const faltando = ['DATABASE_URL', 'JWT_SECRET'].filter((nome) => !env[nome]);
  if (faltando.length) throw new Error('configuração ausente: ' + faltando.join(', '));
  return { porta: Number(env.PORT ?? '3000'), banco: env.DATABASE_URL };
}

console.log(JSON.stringify(carregaConfig({ DATABASE_URL: 'postgres://dev', JWT_SECRET: 'x' })));
try {
  carregaConfig({ PORT: '8080', JWT_SECRET: '' });
} catch (e) {
