const passos = [
  'FROM node:24-slim',
  'COPY package.json package-lock.json',
  'RUN npm ci',
  'COPY src',
  'RUN npm run build',
];

function build(arquivoAlterado: string): string {
  let refaz = false;
  return passos
    .map((p) => {
      if (p.startsWith('COPY') && p.includes(arquivoAlterado)) refaz = true;
      return refaz ? 'REFAZ' : 'cache';
    })
    .join(' ');
}

console.log(build('src'));
console.log(build('package.json'));

const dependeDe: Record<string, string[]> = {
  web: ['api'],
  api: ['db', 'redis'],
  db: [],
  redis: [],
};

const ordem: string[] = [];
function sobe(servico: string) {
  if (ordem.includes(servico)) return;
  for (const d of dependeDe[servico] ?? []) sobe(d);
  ordem.push(servico);
}

Object.keys(dependeDe).forEach(sobe);
console.log(ordem.join(' > '));

const esquemas: Record<string, string[]> = {
  antigo: ['nome'],
  expandido: ['nome', 'titulo'],
  contraido: ['titulo'],
};
const colunasQueUsa: Record<string, string[]> = { v1: ['nome'], v2: ['titulo'] };

for (const [esquema, colunas] of Object.entries(esquemas)) {
  const funcionam = Object.entries(colunasQueUsa)
    .filter(([, usa]) => usa.every((c) => colunas.includes(c)))
    .map(([versao]) => versao);
  console.log(esquema + ':', funcionam.join(' e '));
}

import { AsyncLocalStorage } from 'node:async_hooks';

const contexto = new AsyncLocalStorage<{ requestId: string }>();
const espera = (ms: number) => new Promise((r) => setTimeout(r, ms));
const log = (msg: string) =>
  console.log(JSON.stringify({ msg, requestId: contexto.getStore()?.requestId }));

async function buscaTarefas() {
  await espera(20);
  log('consulta');
}

async function atende(requestId: string, ms: number) {
  await contexto.run({ requestId }, async () => {
    log('inicio');
    await espera(ms);
    await buscaTarefas();
    log('fim');
  });
}

await Promise.all([atende('req-a', 60), atende('req-b', 20)]);

const janelaSeg = 10;
const reqs = [
  { status: 200, ms: 40 },
  { status: 200, ms: 55 },
  { status: 500, ms: 900 },
  { status: 200, ms: 35 },
  { status: 404, ms: 20 },
];

const taxa = reqs.length / janelaSeg;
const erros = reqs.filter((r) => r.status >= 500).length;
const media = reqs.reduce((soma, r) => soma + r.ms, 0) / reqs.length;

console.log('Rate:', taxa, 'req/s');
console.log('Errors:', erros, 'de', reqs.length);
console.log('Duration média:', media, 'ms');

import http from 'node:http';

let pronto = true;
const servidor = http.createServer((req, res) => {
  res.setHeader('connection', 'close');
  if (req.url === '/ready') { res.statusCode = pronto ? 200 : 503; res.end(); return; }
  setTimeout(() => res.end('ok'), 80);
});

function aoReceberSigterm() { // em produção: process.on('SIGTERM', aoReceberSigterm)
  pronto = false;
  return new Promise<void>((fechou) => servidor.close(() => fechou()));
}

servidor.listen(0, '127.0.0.1', async () => {
  const base = 'http://127.0.0.1:' + (servidor.address() as { port: number }).port;
  console.log('ready antes:', (await fetch(base + '/ready')).status);
  const lenta = fetch(base + '/trabalho').then((r) => r.text());
  await new Promise((r) => setTimeout(r, 30));
  const fechou = aoReceberSigterm();
  const nova = await fetch(base + '/ready').then((r) => r.status, () => 'recusada');
  console.log('conexão nova:', nova);
  console.log('em andamento:', await lenta);
  await fechou;
  console.log('servidor fechado');
});

const ms = [12, 15, 11, 14, 13, 16, 12, 900, 15, 13, 14, 12, 11, 13, 15, 14, 12, 16, 13, 1200];

const ordenado = [...ms].sort((a, b) => a - b);
const percentil = (p: number) => ordenado[Math.ceil((p / 100) * ordenado.length) - 1];
const media = ms.reduce((soma, x) => soma + x, 0) / ms.length;

console.log('média:', media);
console.log('p50:', percentil(50));
