const balde = (id: string) => [...id].reduce((h, c) => (h * 31 + c.charCodeAt(0)) % 100, 0);
const ligada = (id: string, porcentagem: number) => balde(id) < porcentagem;

const usuarios = ['ana', 'bia', 'davi', 'eva', 'gil', 'hugo'];

for (const pct of [0, 10, 25, 50, 100]) {
  const quem = usuarios.filter((u) => ligada(u, pct));
  console.log(pct + '%:', quem.join(',') || '-');
}

